H('405.d.3.B',3,"A team member on an engineering project is expected to complete assigned tasks and:","communicate problems early",["hide issues","avoid meetings","work alone only"],"Early communication prevents delays.")
H('405.d.3.B',4,"Which role approves major changes and resolves conflicts on a project?","project manager or sponsor",["intern","visitor","supplier's driver"],"Leaders decide.")
H('405.d.3.C',3,"Software that tracks tasks, deadlines, and team assignments is a:","project management tool",["music player","game","browser extension only"],"Tools coordinate work.")
H('405.d.3.C',4,"A critical path shows the sequence of tasks that determines the:","shortest possible project length",["number of staff","color of charts","price of parts"],"Critical path controls duration.")
H('405.d.3.D',3,"Keeping drawings, reports, and emails in organized folders is part of:","document management",["advertising","shipping","recruiting"],"Organization saves time.")
H('405.d.3.D',4,"A numbering system for drawing revisions prevents the team from using:","outdated information",["new tools","clean files","backups"],"Revision control avoids errors.")
H('405.d.3.E',3,"A requirement that a device must weigh under 2 kg is a:","constraint on the design",["suggestion","joke","color"],"Requirements limit design.")
H('405.d.3.E',4,"When a deliverable changes from a paper report to a working model, the team must adjust the:","schedule and resources",["project name","team shirts","office layout"],"Changes affect plans.")
H('405.d.3.F',3,"The budget for a robot project includes parts, equipment, and:","labor hours",["rumors","weather","snacks only"],"Labor is a cost.")
H('405.d.3.F',4,"If a team spends $620 of a $800 budget, the remaining amount is:","$180",["$120","$220","$1,420"],"800 - 620 = 180.")
H('405.d.3.G',3,"Management of change is especially important in industries such as chemical processing because small changes can create:","new safety risks",["new colors","better lunches","fewer tasks"],"Process changes can cause accidents.")
H('405.d.3.G',4,"A MOC form typically records what is changing, why, and who:","approved the change",["ate lunch","painted the shop","joined the club"],"Approvals create accountability.")
H('405.d.4.A',3,"Respirators protect workers from breathing:","dust, fumes, or vapors",["bright light","loud noise","cold air"],"Respirators filter air.")
H('405.d.4.A',4,"Cut-resistant gloves are chosen for tasks involving:","sharp edges",["wet paint","hot grills","loud noise"],"Match PPE to hazard.")
H('405.d.4.B',3,"Safety guidelines from OSHA apply to:","most workplaces in the United States",["only schools","only farms","only offices"],"OSHA sets workplace standards.")
H('405.d.4.B',4,"A written safe operating procedure for a machine should be:","followed every time the machine is used",["ignored","used when convenient","hidden"],"Procedures work only when followed.")
H('405.d.4.C',3,"Lockout/tagout (LOTO) procedures prevent machines from:","starting up unexpectedly during service",["cooling down","getting dirty","being sold"],"LOTO controls hazardous energy.")
H('405.d.4.C',4,"Under LOTO, the person who places a lock on a machine should be the only one to:","remove it",["ignore it","paint it","buy it"],"Personal locks protect workers.")
H('405.d.4.D',3,"Wet floors in a work area should be marked with:","a warning sign",["decorations","music","flowers"],"Signs warn of slips.")
H('405.d.4.D',4,"Keeping aisles free of boxes helps workers to:","exit quickly in an emergency",["store more","walk slower","hide tools"],"Clear paths save lives.")
H('405.d.4.E',3,"Working near overhead power lines can cause:","electrocution",["boredom","cooling","hearing"],"Contact with lines is deadly.")
H('405.d.4.E',4,"Using a metal ladder near live wires is dangerous because metal:","conducts electricity",["blocks it","absorbs it","is heavy"],"Metal ladders conduct current.")
H('405.d.4.F',3,"Wiring that is properly grounded and protected by circuit breakers is an example of an:","electrical hazard control",["art project","sales tool","filing system"],"Controls reduce risk.")
H('405.d.4.F',4,"Wearing insulated gloves rated for the voltage is an example of:","personal protective equipment",["a work schedule","a suggestion","a budget item"],"PPE protects workers.")
H('405.d.4.G',3,"A first aid kit is a common:","workplace safety resource",["tool for drawing","form of payment","software"],"First aid is part of safety planning.")
H('405.d.4.G',4,"An emergency action plan describes what workers do during a fire, a spill, or a:","severe weather event",["lunch break","pay raise","sales call"],"Plans cover multiple emergencies.")
H('405.d.4.H',3,"Used coolant and solvents from machining must be:","disposed of as hazardous waste",["poured on the ground","mixed together","stored in drink bottles"],"Hazardous waste has special rules.")
H('405.d.4.H',4,"A Safety Data Sheet tells workers how to dispose of a chemical and what to do after:","an exposure or spill",["a holiday","a promotion","a meeting"],"SDS includes first aid and spill steps.")
H('405.d.4.I',3,"Cleaning and oiling a lathe on a schedule is an example of:","preventive maintenance",["decoration","delay","storage"],"Scheduled care prevents failure.")
H('405.d.4.I',4,"Before cleaning a machine, a worker should:","turn it off and lock it out",["leave it running","remove guards","speed it up"],"Safe maintenance begins with LOTO.")
H('405.d.4.J',3,"Heavy materials should be stored:","low and stable",["high and loose","in walkways","on top of cabinets"],"Low storage prevents falls.")
H('405.d.4.J',4,"A tool with a mushroomed head, such as a chisel, should be:","repaired or replaced",["used harder","painted","stored in a pocket"],"Damaged tools shatter.")
H('405.d.4.K',3,"Ignoring a leaking hydraulic hose can lead to:","an injury or equipment failure",["savings","faster work","a bonus"],"Neglect leads to harm.")
H('405.d.4.K',4,"A worker injured because of poor maintenance may bring a claim that the employer was:","negligent",["generous","punctual","efficient"],"Negligence creates liability.")
H('405.d.5.A',3,"In a team design project, the roles might include a leader, a recorder, and a:","builder or tester",["spectator","critic only","mascot"],"Roles divide the work.")
H('405.d.5.A',4,"Rotating roles on a project helps members to:","learn different skills",["avoid work","reduce results","blame others"],"Rotation builds experience.")
H('405.d.5.B',3,"A skill-building plan for a team member might include a training class or:","practice with a mentor",["no effort","skipping work","complaints"],"Plans grow skills.")
H('405.d.5.B',4,"If a member is strong in drawing but weak in presenting, the team can plan for them to:","practice presenting while others help",["never present","never draw","quit"],"Growth plans use strengths.")
H('405.d.5.C',3,"Showing up on time and completing tasks shows:","dependability",["laziness","distraction","secrecy"],"Reliable members build trust.")
H('405.d.5.C',4,"Giving a teammate constructive feedback means pointing out how to:","improve, with respect",["embarrass","argue","gossip"],"Feedback should help.")
H('405.d.5.D',3,"A leader of a design team is responsible for helping the team to:","reach its goals",["avoid work","blame members","work alone"],"Leaders guide.")
H('405.d.5.D',4,"A team that agrees on goals, roles, and rules at the start is more likely to:","work smoothly",["fail","argue","quit"],"Norms reduce conflict.")
H('405.d.6.A',3,"Rapid prototyping is a technique that quickly produces a:","working or physical model",["final report","budget","slogan"],"Rapid prototypes test ideas fast.")
H('405.d.6.A',4,"Sketching many versions of one idea in a short time is a technique called:","thumbnail sketching",["tracing","erasing","rendering"],"Quick sketches generate options.")
H('405.d.6.B',3,"A team evaluates a constraint such as cost by asking how it limits the:","possible solutions",["time of day","team size only","school colors"],"Constraints narrow options.")
H('405.d.6.B',4,"When a constraint changes, the team should reevaluate:","whether current solutions still fit",["the project name","lunch times","shirt colors"],"Constraints can alter designs.")
H('405.d.6.C',3,"Evidence-based decision-making relies on:","data from tests and research",["hunches","popularity","coin flips"],"Evidence guides decisions.")
H('405.d.6.C',4,"A team that improves a design after test data show a weakness is:","using evidence to improve",["ignoring evidence","guessing","giving up"],"Data-driven improvement.")
H('405.d.6.D',3,"A Pugh matrix compares design options against a:","baseline design",["lunch menu","pencil","calendar"],"Pugh compares to a reference.")
H('405.d.6.D',4,"In a decision matrix, the option with the highest total score is generally:","the preferred solution",["rejected","unrelated","hidden"],"Highest score wins.")
H('405.d.6.E',3,"An organized notebook includes a table of contents and numbered:","pages",["colors","songs","jokes"],"Pages are numbered.")
H('405.d.6.E',4,"Recording a failed experiment in the notebook is important because it:","prevents repeating the same mistake",["wastes pages","hides progress","has no value"],"Failures teach.")
H('405.d.6.F',3,"An engineering portfolio shows examples of a person's:","projects and skills",["pets","family","lunch"],"Portfolios showcase work.")
H('405.d.6.F',4,"To justify a design decision in a portfolio, a student should include:","evidence such as test results",["opinions only","a joke","only pictures of the team"],"Justification needs data.")
H('405.d.7.A',3,"Analyzing a bicycle as a system means studying how its parts such as gears, chain, and brakes:","work together",["look different","cost less","sound alike"],"Systems interact.")
H('405.d.7.A',4,"Drawing a block diagram of a product helps show how its subsystems are:","connected",["priced","colored","named after people"],"Block diagrams show relationships.")
H('405.d.7.B',3,"Ethical reverse engineering means studying a product to learn how it works without:","copying protected designs illegally",["learning","drawing","measuring"],"Respect patents and copyrights.")
H('405.d.7.B',4,"Reverse engineering a competitor's product to copy its patented feature would be:","illegal",["required","routine","legal always"],"Patent infringement is unlawful.")
