H('405.d.8.K',4,"An advanced template may include layer standards, text styles, and:","plot settings",["song lists","passwords","recipes"],"Templates package standards.")
H('405.d.8.L',3,"Polar tracking helps a drafter draw lines at set:","angles",["colors","names","prices"],"Polar tracking snaps to angles.")
