H('405.d.8.M',4,"When the source file of an xref changes, the main drawing can:","reload to show the update",["lose its layers","change name","delete itself"],"Xrefs update.")
H('405.d.8.N',3,"Parametric modeling tools allow the model to change when a:","dimension value is edited",["color is picked","file is renamed","tab is closed"],"Parameters drive geometry.")
