H('405.d.8.O',3,"An animated assembly shows how parts:","move and fit together",["are priced","are named","are stored"],"Animation shows motion.")
H('405.d.8.O',4,"A motion study in an assembly model can reveal whether two moving parts will:","collide",["print","save","rename"],"Interference checks find collisions.")
H('405.d.9.A',3,"Delineating the steps of the design process for a prototype begins with defining the problem and generating:","possible solutions",["finished goods","invoices","press releases"],"Design starts with problem and ideas.")
H('405.d.9.A',4,"Implementing the plan after choosing a solution means:","building and testing the prototype",["ending the project","buying a bigger budget","hiding the plan"],"Implementation follows planning.")
H('405.d.9.B',3,"Before using a drill press, a student should secure the workpiece with a:","clamp or vise",["bare hand","glove","friend's hand"],"Clamp the work.")
