H('405.d.9.H',4,"The strongest evidence in a prototype presentation is:","measured test results",["opinions","guesses","advertising"],"Data is credible.")
H('405.d.10.A',3,"A multi-system problem might involve mechanical, electrical, and:","software systems",["art supplies","cooking tools","sports gear"],"Complex products combine systems.")
H('405.d.10.A',4,"A robotic vacuum is a multi-system product because it combines motors, sensors, and a:","control program",["rug","nap","plug-in clock only"],"It integrates hardware and software.")
H('405.d.10.B',3,"Documenting goals and requirements for a complex project makes sure all team members:","share the same expectations",["avoid work","hide tasks","argue"],"Documented requirements align teams.")
H('405.d.10.B',4,"A requirement is testable when it includes a:","measurable value",["feeling","color name","slogan"],"Testable requirements are measurable.")
H('405.d.10.C',3,"Design constraints on a project can include materials, personnel, and:","time",["moods","songs","slogans"],"Time is a constraint.")
H('405.d.10.C',4,"A limit on available motors forces a team to select a design that works with the:","parts on hand",["unlimited catalog","imagination only","wishes"],"Constraints guide selection.")
H('405.d.10.D',3,"Health, safety, and environmental concerns are examples of design:","parameters",["nicknames","rumors","themes"],"They shape design.")
