H('406.d.2.F',3,"A spreadsheet is useful for organizing quantitative data because it can:","calculate and graph values",["only store pictures","play sounds","print alone"],"Spreadsheets compute and chart.")
H('406.d.2.F',4,"Observations such as 'the weld looks smooth' are examples of:","qualitative data",["quantitative data","a conclusion","a law"],"Descriptions are qualitative.")
H('406.d.2.G',3,"A flow chart of a manufacturing line is a model of a:","process",["person","mineral","planet"],"Process models show steps.")
