H('406.d.2.H',3,"A hypothesis becomes more reliable as it is:","tested repeatedly with consistent results",["repeated aloud","published without tests","ignored"],"Replication builds support.")
H('406.d.2.H',4,"The law of conservation of energy remains a law because it has:","been supported by countless experiments",["been voted on","never been tested","one proof"],"Laws rest on evidence.")
H('406.d.3.A',3,"A physical scale model of a dam may not capture all the effects of:","full-size water pressure",["color","name","logo"],"Scaling can omit real effects.")
H('406.d.3.A',4,"A model that is simpler than reality is useful when it still captures the:","important features of the system",["unneeded details","random noise","packaging"],"Good models focus on what matters.")
H('406.d.3.B',3,"A scatter plot with points that cluster near a line going upward shows a:","positive correlation",["negative correlation","no data","perfect copy"],"Both variables rise together.")
H('406.d.3.B',4,"If one test result differs greatly from all the others, an analyst should:","investigate it as a possible outlier",["delete it silently","double it","average it twice"],"Outliers need investigation.")
